[{"order":1,"type":"heading","text":"TFRecord Generation and Parsing in TensorFlow"},{"order":2,"type":"paragraph","text":"TFRecord is a simple format for storing a sequence of binary records. TensorFlow uses this format extensively for training data to maximize I/O throughput. This tutorial demonstrates how to serialize data into TFRecord files and parse them back during the input pipeline stage."},{"order":3,"type":"subheading","text":"1. Understanding TFRecord Structure"},{"order":4,"type":"paragraph","text":"At its core, a TFRecord file contains bytes. To serialize data, you must wrap your training data into protocol buffers known as tf.train.Example. Each Example contains a features message, which is a dictionary mapping feature names to tf.train.Feature objects."},{"order":5,"type":"subheading","text":"2. Generating TFRecords"},{"order":6,"type":"paragraph","text":"The following code snippet demonstrates how to convert raw data (such as integers, floats, and byte strings) into tf.train.Example protos and write them to disk using tf.io.TFRecordWriter."},{"order":7,"type":"code","text":"import tensorflow as tf
import numpy as np

def _bytes_feature(value):
    if isinstance(value, type(tf.constant(0))):
        value = value.numpy()
    return tf.train.Feature(bytes_list=tf.train.BytesList(value=[value]))

def _float_feature(value):
    return tf.train.Feature(float_list=tf.train.FloatList(value=[value]))

def _int64_feature(value):
    return tf.train.Feature(int64_list=tf.train.Int64List(value=[value]))

# Create a dummy dataset
image_data = np.random.rand(28, 28, 3).astype(np.float32).tostring()
label = 5
pixels = 784

def serialize_example(image_buffer, label, pixels):
    feature = {
        'image': _bytes_feature(image_buffer),
        'label': _int64_feature(label),
        'pixels': _int64_feature(pixels),
    }
    example_proto = tf.train.Example(features=tf.train.Features(feature=feature))
    return example_proto.SerializeToString()

# Write to TFRecord file
file_path = 'output.tfrecord'
with tf.io.TFRecordWriter(file_path) as writer:
    example = serialize_example(image_data, label, pixels)
    writer.write(example)"},{"order":8,"type":"subheading","text":"3. Parsing TFRecords"},{"order":9,"type":"paragraph","text":"To read the generated TFRecord file back into memory, we use tf.data.TFRecordDataset and decode the serialized strings using a feature description dictionary."},{"order":10,"type":"code","text":"import tensorflow as tf

# Define feature description for parsing
feature_description = {
    'image': tf.io.FixedLenFeature([], tf.string),
    'label': tf.io.FixedLenFeature([], tf.int64),
    'pixels': tf.io.FixedLenFeature([], tf.int64),
}

def parse_function(example_proto):
    return tf.io.parse_single_example(example_proto, feature_description)

# Create dataset from TFRecord file
parsed_dataset = tf.data.TFRecordDataset('output.tfrecord')
parsed_dataset = parsed_dataset.map(parse_function)

# Iterate and inspect parsed data
for parsed_record in parsed_dataset.take(1):
    print('Label:', parsed_record['label'].numpy())
    print('Pixels:', parsed_record['pixels'].numpy())"},{"order":11,"type":"subheading","text":"Best Practices"},{"order":12,"type":"bullet_point","text":"Use multiple TFRecord files (sharding) for large datasets to enable parallel reading during distributed training."},{"order":13,"type":"bullet_point","text":"Always batch and prefetch your dataset using tf.data to prevent I/O bottlenecks from starving your GPU."}]
